import java.util.*;

class Solution {
    public int[] smallestRange(int[][] nums) {
        if (nums == null || nums.length == 0) return new int[]{0, 0};
        int k = nums.length;
        PriorityQueue<int[]> pq = new PriorityQueue<>(k, (a, b) -> Integer.compare(a[0], b[0]));
        int curMax = Integer.MIN_VALUE;
        for (int i = 0; i < k; i++) {
            int val = nums[i][0];
            pq.offer(new int[]{val, i, 0});
            curMax = Math.max(curMax, val);
        }
        int[] result = {pq.peek()[0], curMax};
        while (pq.size() == k) {
            int[] min = pq.poll();
            int listIdx = min[1], elemIdx = min[2];
            if (elemIdx + 1 >= nums[listIdx].length) break;
            int next = nums[listIdx][elemIdx + 1];
            pq.offer(new int[]{next, listIdx, elemIdx + 1});
            curMax = Math.max(curMax, next);
            if (curMax - pq.peek()[0] < result[1] - result[0]) {
                result[0] = pq.peek()[0];
                result[1] = curMax;
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int[] smallestRange(int[][] nums) {
        if (nums == null || nums.length == 0) return new int[]{0, 0};
        int k = nums.length;
        List<int[]> merged = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < nums[i].length; j++) {
                merged.add(new int[]{nums[i][j], i});
            }
        }
        if (merged.isEmpty()) return new int[]{0, 0};
        Collections.sort(merged, (a, b) -> Integer.compare(a[0], b[0]));

        int[] count = new int[k];
        int covered = 0;
        int left = 0;
        int bestLeft = 0;
        int bestRight = Integer.MAX_VALUE;

        for (int right = 0; right < merged.size(); right++) {
            int listIdx = merged.get(right)[1];
            if (count[listIdx] == 0) covered++;
            count[listIdx]++;

            while (covered == k) {
                int rangeLeft = merged.get(left)[0];
                int rangeRight = merged.get(right)[0];
                if (rangeRight - rangeLeft < bestRight - bestLeft) {
                    bestLeft = rangeLeft;
                    bestRight = rangeRight;
                }
                int leftList = merged.get(left)[1];
                count[leftList]--;
                if (count[leftList] == 0) covered--;
                left++;
            }
        }
        return new int[]{bestLeft, bestRight};
    }
}
